LEVELS = {"facile": "easy", "medio": "medium", "difficile": "hard", "esperto": "expert",
          "campione": "champion"}


def translate_games(apps, schema_editor):
    """Partite registrate prima: codici in inglese, nickname copiati dal Player, mosse
    rigiocate per dare il nome alle pedine (dal formato [giocatore, q, r, d, secondi]).
    Le regole senza no_pushback sono di prima che esistesse: valeva False."""
    Game = apps.get_model("play", "Game")
    for game in Game.objects.select_related("player_a", "player_b"):
        game.rules.setdefault("no_pushback", False)
        if game.mode == "amico":
            game.mode = "friend"
        game.level = LEVELS.get(game.level, game.level)
        for color, player in (("A", game.player_a), ("B", game.player_b)):
            if player is not None and game.bot_side != color:
                setattr(game, f"name_{color.lower()}", player.name)
        if game.moves and isinstance(game.moves[0], list):
            from hexpush.game import PASS, legal_moves
            from hexpush.rules import Ruleset
            from play.matches import Match
            match = Match(Ruleset(**game.rules))
            for p, q, r, d, t in game.moves:
                move = PASS if q is None else next(
                    m for m in legal_moves(match.state)
                    if m is not PASS and (m.q, m.r, m.d) == (q, r, d))
                match.push(move, t)
            game.moves = [rec for _, _, rec in match.log]
            game.pieces = match.pieces
        elif not game.pieces:
            from hexpush.game import new_game
            from hexpush.rules import Ruleset
            from play.matches import piece_names
            game.pieces = {name: list(c) for c, name
                           in piece_names(new_game(Ruleset(**game.rules)).board).items()}
        game.save()


